import os
import shutil
from contextlib import contextmanager
from time import sleep

from hran_pacman.bases.logger import LOGGER
from hran_pacman.config import config
from hran_pacman.dyingfile import DyingFile
from hran_pacman.storages_bases import (PERMISSION_LEVEL, BaseStorage,
                                        PermanentStorageBase)


class TemporaryStorage(BaseStorage):
    """Temporary container representation.

    Provides temporary location for package to downloaded to,
    eliminates risk of leaving trash in final destinations
    because stands as a place of package
    downloading and validation.

    Serves as place, from which validated package will
    be redistributed to other, permanent destination places.
    """

    def __init__(self, baseline, package_name):
        super(TemporaryStorage, self).__init__(config.get_local_path(), baseline, package_name)

    @contextmanager
    def prepare_environment(self):
        """Prepare temporary container,
        keep it as long as needed then cleanup.
        """
        self.create_storage()
        cwd = os.getcwd()
        os.chdir(self.container_path)
        try:
            yield
        finally:
            os.chdir(cwd)
            self._remove_storage()

    def create_storage(self):
        if os.path.exists(self.container_path):
            LOGGER.debug("Temporary storage already exists, removing it before creating a new one")
            self._remove_storage()
            sleep(3)
        LOGGER.info("Creating storage {}".format(self.container_path))
        os.mkdir(self.container_path)

    def _remove_storage(self):
        shutil.rmtree(self.container_path)

    @property
    def container_path(self):
        return os.path.join(self.root_path, '{}___TMP'.format(self.baseline))


class RemoteStorage(PermanentStorageBase):
    """
    Representation of remote storage,

    manage over locking system automatically
    as part of environment preparation.
    """

    locker = DyingFile

    def __init__(self, baseline, package_name):
        super(RemoteStorage, self).__init__(config.get_remote_path(), baseline, package_name)
        self._setup_locker()

    def _setup_locker(self):
        self.lock_file_name = self.baseline + "___LOCK"
        self.lock_path = os.path.join(self.root_path, self.lock_file_name)
        self.lock = self.locker(self.lock_path)

    def prepare_environment(self):
        self.create_storage()

    def _package_available(self):
        LOGGER.info("Checking if package exists at {}".format(self.package_path))
        return self.lock.check() and os.path.exists(self.package_path)


class LocalStorage(PermanentStorageBase):
    """
    Final, local destination path for package,
    should target local directory only.
    """

    def __init__(self, baseline, package_name):
        super(LocalStorage, self).__init__(config.get_local_path(), baseline, package_name)

    def prepare_environment(self):
        if not os.path.exists(self.root_path):
            LOGGER.info("Local storage at {} does not exist, creating one".format(self.root_path))
            self.create_storage()
